function Cuerpo({ who, alto = 200, saluda = true }) {
  return (
    <img
      src={ART[who].cuerpo}
      alt={PERSONAJES[who].nombre}
      className={saluda ? "flota" : ""}
      style={{ height: alto, width: "auto", display: "block", margin: "0 auto" }}
    />
  );
}

function Cara({ who, size = 44 }) {
  return (
    <img
      src={ART[who].cara}
      alt=""
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        display: "block",
        objectFit: "cover",
        background: "#fff",
        border: "2px solid currentColor",
      }}
    />
  );
}

/* ------------------------------------------------------------------ */

export default function JuegoMascotas() {
  const [pantalla, setPantalla] = useState("inicio");
  const [quien, setQuien] = useState(null);
  const [mensajes, setMensajes] = useState([]);
  const [opciones, setOpciones] = useState([]);
  const [puntos, setPuntos] = useState(0);
  const [nivel, setNivel] = useState(0);
  const [turnos, setTurnos] = useState(0);
  const [cargando, setCargando] = useState(false);
  const [texto, setTexto] = useState("");
  const [temblor, setTemblor] = useState(false);
  const [insignias, setInsignias] = useState([]);
  const finRef = useRef(null);

  const p = quien ? PERSONAJES[quien] : null;
  const mision = p ? p.misiones[Math.min(nivel, p.misiones.length - 1)] : null;

  useEffect(() => {
    finRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [mensajes, cargando]);

  function empezar(id) {
    const pj = PERSONAJES[id];
    setQuien(id);
    setPuntos(0);
    setNivel(0);
    setTurnos(0);
    setInsignias([]);
    setMensajes([
      {
        de: "bot",
        texto: `¡Hola! Soy ${pj.nombre}, ${pj.apodo}. Traigo tres misiones y necesito un compañero de equipo. ¿Le entramos a la primera?`,
      },
      { de: "bot", texto: pj.misiones[0].escenario },
    ]);
    setOpciones(pj.misiones[0].opciones.map((o) => o.texto));
    setPantalla("juego");
    if (id === "sismo") sacudir();
  }

  function sacudir() {
    setTemblor(true);
    setTimeout(() => setTemblor(false), 1300);
  }

  async function responder(entrada) {
    if (!entrada.trim() || cargando) return;
    const historial = [...mensajes, { de: "yo", texto: entrada }];
    setMensajes(historial);
    setOpciones([]);
    setTexto("");
    setCargando(true);

    const sistema = `${p.persona}

Estás jugando una aventura por turnos con un niño o niña. Misión actual: "${mision.titulo}" (${mision.lugar}).
Escenario: ${mision.escenario}
Respuesta correcta esperada: ${mision.opciones.find((o) => o.ok).texto}
Por qué: ${mision.explicacion}
Dato curioso disponible: ${mision.dato}

Reglas:
- Español de México, sencillo, frases cortas. Máximo 45 palabras en "mensaje".
- Si la respuesta del jugador es buena, celébrala y explica por qué funciona. Si no, corrige con cariño y sin miedo, y di qué hacer en su lugar.
- Nunca describas lesiones, muertes ni escenas que asusten.
- Si el jugador pregunta algo fuera de tema, respóndele breve y regrésalo a la misión.
- Marca "misionCompleta": true en cuanto el jugador ya entendió la idea clave (turno 1 o 2, no lo alargues).

Responde ÚNICAMENTE con este JSON, sin texto extra ni backticks:
{"reaccion":"3 palabras máximo","correcto":true,"mensaje":"tu respuesta en personaje","opciones":["opción corta 1","opción corta 2","opción corta 3"],"puntos":10,"dato":"dato curioso o cadena vacía","misionCompleta":false}`;

    let datos = null;
    try {
      const r = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 1000,
          system: sistema,
          messages: historial.slice(-8).map((m) => ({
            role: m.de === "yo" ? "user" : "assistant",
            content: m.texto,
          })),
        }),
      });
      const data = await r.json();
      const crudo = data.content
        .map((c) => (c.type === "text" ? c.text : ""))
        .join("")
        .replace(/```json|```/g, "")
        .trim();
      datos = JSON.parse(crudo);
    } catch (e) {
      const acerto = mision.opciones.some(
        (o) => o.ok && entrada.toLowerCase().includes(o.texto.toLowerCase().slice(0, 14))
      );
      datos = {
        reaccion: acerto ? "¡Esa es!" : "Casi, casi",
        correcto: acerto,
        mensaje: `${mision.explicacion} ${acerto ? "Lo tenías clarísimo." : "Ahora ya lo sabes para la próxima."}`,
        opciones: [],
        puntos: acerto ? 15 : 5,
        dato: mision.dato,
        misionCompleta: true,
      };
    }

    const ganados = Math.max(0, Math.min(20, Number(datos.puntos) || 0));
    setPuntos((v) => v + ganados);
    setMensajes((m) => [
      ...m,
      {
        de: "bot",
        texto: datos.mensaje,
        reaccion: datos.reaccion,
        dato: datos.dato,
        ganados,
      },
    ]);

    const nuevoTurno = turnos + 1;
    setTurnos(nuevoTurno);

    if (datos.misionCompleta || nuevoTurno >= 3) {
      setInsignias((b) => [...b, mision.titulo]);
      setTimeout(() => avanzar(), 900);
    } else {
      setOpciones(Array.isArray(datos.opciones) ? datos.opciones.slice(0, 3) : []);
    }
    setCargando(false);
  }

  function avanzar() {
    const siguiente = nivel + 1;
    if (siguiente >= p.misiones.length) {
      setPantalla("fin");
      return;
    }
    const m = p.misiones[siguiente];
    setNivel(siguiente);
    setTurnos(0);
    setMensajes((prev) => [
      ...prev,
      { de: "sistema", texto: `Misión cumplida. Siguiente: ${m.titulo}` },
      { de: "bot", texto: m.escenario },
    ]);
    setOpciones(m.opciones.map((o) => o.texto));
    if (quien === "sismo") sacudir();
  }

  const t = p ? p.tema : PERSONAJES.sismo.tema;

  const css = `
    .juego * { box-sizing: border-box; }
    .juego {
      --fondo:${t.fondo}; --fondo2:${t.fondo2}; --tinta:${t.tinta};
      --acento:${t.acento}; --acento2:${t.acento2}; --linea:${t.linea};
      font-family: "Trebuchet MS", "Segoe UI", Verdana, system-ui, sans-serif;
      color: var(--tinta);
      background:
        repeating-linear-gradient(0deg, transparent 0 39px, rgba(255,255,255,.5) 39px 40px),
        repeating-linear-gradient(90deg, transparent 0 39px, rgba(255,255,255,.5) 39px 40px),
        linear-gradient(170deg, var(--fondo) 0%, var(--fondo2) 100%);
      min-height: 100%; padding: 14px; border-radius: 18px;
    }
    .marco {
      max-width: 720px; margin: 0 auto;
      border: 4px solid var(--tinta); border-radius: 22px;
      background: rgba(255,255,255,.66); overflow: hidden;
      box-shadow: 0 10px 0 rgba(0,0,0,.14);
    }
    .hud { display: flex; align-items: center; gap: 12px; padding: 10px 14px;
      background: var(--acento); color: #fff; border-bottom: 4px solid var(--tinta); }
    .hud h1 { font-size: 17px; margin: 0; }
    .hud p { margin: 1px 0 0; font-size: 12px; opacity: .92; }
    .marcador { margin-left: auto; background: #fff; color: var(--tinta);
      border: 3px solid var(--tinta); border-radius: 999px; padding: 4px 12px;
      font-weight: bold; font-size: 15px; white-space: nowrap; }
    .barra { display: flex; gap: 6px; padding: 8px 14px; background: rgba(255,255,255,.72);
      border-bottom: 2px dashed var(--linea); align-items: center; font-size: 12px; }
    .paso { width: 26px; height: 9px; border-radius: 5px; background: var(--linea); }
    .paso.on { background: var(--acento2); }
    .chat { padding: 16px 14px; max-height: 360px; overflow-y: auto;
      display: flex; flex-direction: column; gap: 14px; }
    .fila { display: flex; gap: 10px; align-items: flex-end; color: var(--tinta); }
    .fila.mia { justify-content: flex-end; }
    .globo { background: #fff; border: 3px solid var(--tinta); border-radius: 16px;
      padding: 10px 14px; max-width: 78%; line-height: 1.45; font-size: 15px; }
    .globo.mio { background: var(--acento2); color: #fff; }
    .etiqueta { display: inline-block; font-size: 12px; font-weight: bold; color: var(--acento); margin-bottom: 3px; }
    .titulo-mision { align-self: center; background: var(--tinta); color: #fff;
      font-size: 12px; padding: 5px 14px; border-radius: 999px; }
    .dato { margin-top: 8px; padding-top: 8px; border-top: 2px dotted var(--linea); font-size: 13px; }
    .ganados { font-size: 13px; font-weight: bold; color: var(--acento2); margin-top: 6px; }
    .opciones { display: flex; flex-direction: column; gap: 8px; padding: 4px 14px 14px; }
    .opciones button, .enviar { font: inherit; cursor: pointer; text-align: left;
      background: #fff; border: 3px solid var(--tinta); border-radius: 14px;
      padding: 11px 14px; font-size: 15px; color: var(--tinta);
      box-shadow: 0 4px 0 var(--tinta); transition: transform .08s, box-shadow .08s; }
    .opciones button:hover { background: var(--fondo2); }
    .opciones button:active, .enviar:active { transform: translateY(4px); box-shadow: 0 0 0 var(--tinta); }
    .escribe { display: flex; gap: 8px; padding: 0 14px 16px; }
    .escribe input { flex: 1; font: inherit; font-size: 15px; padding: 11px 14px;
      border: 3px solid var(--tinta); border-radius: 14px; background: #fff; color: var(--tinta); }
    .enviar { background: var(--acento); color: #fff; text-align: center; font-weight: bold; }
    .juego :focus-visible { outline: 4px solid var(--acento2); outline-offset: 2px; }
    .cargando { display: flex; gap: 5px; padding: 4px 2px; }
    .cargando span { width: 9px; height: 9px; border-radius: 50%; background: var(--acento); animation: bota .9s infinite; }
    .cargando span:nth-child(2) { animation-delay: .15s; }
    .cargando span:nth-child(3) { animation-delay: .3s; }
    @keyframes bota { 0%,60%,100% { transform: translateY(0); } 30% { transform: translateY(-7px); } }
    .flota { animation: flota 3.4s ease-in-out infinite; }
    @keyframes flota { 0%,100% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-7px) rotate(-1.2deg); } }
    .tiembla { animation: tiembla 1.2s ease-in-out; }
    @keyframes tiembla {
      0%,100% { transform: translate(0,0) rotate(0); }
      20% { transform: translate(-6px,2px) rotate(-.6deg); }
      40% { transform: translate(6px,-2px) rotate(.6deg); }
      60% { transform: translate(-4px,1px) rotate(-.4deg); }
      80% { transform: translate(4px,-1px) rotate(.3deg); }
    }
    .portada { max-width: 760px; margin: 0 auto; text-align: center; padding: 20px 14px 30px; }
    .portada h1 { font-size: 30px; margin: 0 0 6px; line-height: 1.1; color: #10304f; }
    .portada .sub { font-size: 16px; margin: 0 auto 24px; max-width: 46ch; line-height: 1.5; color: #234; }
    .cartas { display: flex; gap: 18px; justify-content: center; flex-wrap: wrap; }
    .carta { flex: 1 1 260px; max-width: 310px; cursor: pointer; font: inherit; color: #10304f;
      background: #fff; border: 4px solid #10304f; border-radius: 24px; padding: 16px;
      box-shadow: 0 8px 0 #10304f; transition: transform .1s, box-shadow .1s;
      display: flex; flex-direction: column; align-items: center; }
    .carta:hover { transform: translateY(-3px); box-shadow: 0 11px 0 #10304f; }
    .carta:active { transform: translateY(4px); box-shadow: 0 2px 0 #10304f; }
    .carta h2 { margin: 12px 0 4px; font-size: 21px; }
    .carta p { margin: 0; font-size: 14px; line-height: 1.45; }
    .carta .juega { display: inline-block; margin-top: 14px; font-weight: bold; font-size: 14px;
      padding: 7px 18px; border-radius: 999px; color: #fff; }
    .final { text-align: center; padding: 22px 18px 32px; }
    .final h2 { font-size: 26px; margin: 12px 0 6px; }
    .lista-insignias { list-style: none; padding: 0; margin: 16px auto; max-width: 320px; text-align: left; }
    .lista-insignias li { background: #fff; border: 3px solid var(--tinta); border-radius: 12px;
      padding: 8px 12px; margin-bottom: 8px; font-size: 14px; }
    @media (prefers-reduced-motion: reduce) { .juego *, .juego *::before { animation: none !important; } }
    @media (max-width: 520px) { .chat { max-height: 300px; } .portada h1 { font-size: 24px; } }
  `;

  if (pantalla === "inicio") {
    return (
      <div className="juego" style={{ background: "linear-gradient(165deg,#dbe9f8 0%,#e8f3d6 100%)" }}>
        <style>{css}</style>
        <div className="portada">
          <h1>Escuadrón Tecnito y Greencito</h1>
          <p className="sub">
            Dos amigos, dos misiones. Uno te enseña qué hacer cuando la tierra se
            mueve; el otro, cómo cuidar el lugar donde vives. Escoge con quién juegas.
          </p>
          <div className="cartas">
            <button className="carta" onClick={() => empezar("sismo")}>
              <Cuerpo who="sismo" alto={210} />
              <h2>Sismo Tecnito</h2>
              <p>{PERSONAJES.sismo.resumen}</p>
              <span className="juega" style={{ background: "#0f6fc4" }}>Jugar 3 misiones</span>
            </button>
            <button className="carta" onClick={() => empezar("green")}>
              <Cuerpo who="green" alto={210} />
              <h2>Greencito</h2>
              <p>{PERSONAJES.green.resumen}</p>
              <span className="juega" style={{ background: "#5aa32a" }}>Jugar 3 misiones</span>
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (pantalla === "fin") {
    return (
      <div className="juego">
        <style>{css}</style>
        <div className="marco">
          <div className="final">
            <Cuerpo who={quien} alto={190} />
            <h2>¡Misiones completas!</h2>
            <p style={{ fontSize: 16 }}>
              Juntaste <strong>{puntos} {p.moneda}</strong> {p.monedaIcono} con {p.nombre}.
            </p>
            <ul className="lista-insignias">
              {insignias.map((b, i) => (
                <li key={i}>{p.monedaIcono} {b}</li>
              ))}
            </ul>
            <div className="opciones" style={{ maxWidth: 330, margin: "0 auto" }}>
              <button onClick={() => empezar(quien === "sismo" ? "green" : "sismo")}>
                Jugar con {quien === "sismo" ? "Greencito" : "Sismo Tecnito"}
              </button>
              <button onClick={() => setPantalla("inicio")}>Volver al inicio</button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="juego">
      <style>{css}</style>
      <div className={`marco ${temblor ? "tiembla" : ""}`}>
        <div className="hud">
          <Cara who={quien} size={46} />
          <div>
            <h1>{p.nombre}</h1>
            <p>{mision.lugar}</p>
          </div>
          <div className="marcador">{p.monedaIcono} {puntos}</div>
        </div>

        <div className="barra">
          {p.misiones.map((m, i) => (
            <div key={m.id} className={`paso ${i <= nivel ? "on" : ""}`} />
          ))}
          <span style={{ marginLeft: 6 }}>
            Misión {nivel + 1} de {p.misiones.length}: {mision.titulo}
          </span>
        </div>

        <div className="chat">
          {mensajes.map((m, i) =>
            m.de === "sistema" ? (
              <div className="titulo-mision" key={i}>{m.texto}</div>
            ) : (
              <div className={`fila ${m.de === "yo" ? "mia" : ""}`} key={i}>
                {m.de === "bot" && <Cara who={quien} size={44} />}
                <div className={`globo ${m.de === "yo" ? "mio" : ""}`}>
                  {m.reaccion && <span className="etiqueta">{m.reaccion}</span>}
                  <div>{m.texto}</div>
                  {m.dato && <div className="dato">🔎 {m.dato}</div>}
                  {m.ganados > 0 && <div className="ganados">+{m.ganados} {p.moneda}</div>}
                </div>
              </div>
            )
          )}
          {cargando && (
            <div className="fila">
              <Cara who={quien} size={44} />
              <div className="globo">
                <div className="cargando"><span /><span /><span /></div>
              </div>
            </div>
          )}
          <div ref={finRef} />
        </div>

        {opciones.length > 0 && !cargando && (
          <div className="opciones">
            {opciones.map((o, i) => (
              <button key={i} onClick={() => responder(o)}>{o}</button>
            ))}
          </div>
        )}

        <div className="escribe">
          <input
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && responder(texto)}
            placeholder={`Pregúntale algo a ${p.nombre}...`}
            aria-label={`Escribe tu mensaje para ${p.nombre}`}
            disabled={cargando}
          />
          <button className="enviar" onClick={() => responder(texto)} disabled={cargando}>
            Enviar
          </button>
        </div>
      </div>
    </div>
  );
}
